import{_ as d,o,c as t,a2 as c}from"./chunks/framework.DoCD98hS.js";const h=JSON.parse('{"title":"Ant Design · 多框架组件与 Pro 模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/catalog/antd.md","filePath":"modules/catalog/antd.md","lastUpdated":1795083939000}'),a={name:"modules/catalog/antd.md"};function r(n,e,i,l,s,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="ant-design-·-多框架组件与-pro-模板" tabindex="-1">Ant Design · 多框架组件与 Pro 模板 <a class="header-anchor" href="#ant-design-·-多框架组件与-pro-模板" aria-label="Permalink to &quot;Ant Design · 多框架组件与 Pro 模板&quot;">​</a></h1><p>合并 Ant Design 系列的框架差异与 React Pro 模板接入说明；Vue 2、Vue 3 和 React 的导出能力分别列出。</p><div class="info custom-block"><p class="custom-block-title">文档骨架</p><p>先占位目录与已核对的代表性能力，不是完整 API 清单。参数、完整示例和逐文件改造细节待本轮实现定稿后补充；待补项不表示已实现或已发布。</p></div><h2 id="包范围" tabindex="-1">包范围 <a class="header-anchor" href="#包范围" aria-label="Permalink to &quot;包范围&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包名</th><th>职责</th></tr></thead><tbody><tr><td><code>@melt-js/comps-vue2-antd</code></td><td>Vue 2 + Ant Design Vue 与 Df 系列</td></tr><tr><td><code>@melt-js/comps-vue3-antd</code></td><td>Vue 3 + Ant Design Vue 基础示例</td></tr><tr><td><code>@melt-js/comps-react-antd</code></td><td>React Ant Design 与 Pro 配套 UI</td></tr><tr><td><code>@melt-js/comps-vue2-antd-pro</code></td><td>Vue 2 + Ant Design Vue 的图表、列表页部件与弹窗 / 加载插件（提供方）</td></tr><tr><td><code>@melt-js/tpl-react-admin-antd-pro</code></td><td>基于 ant-design-pro 完整示例的宿主</td></tr><tr><td><code>@melt-js/tpl-vue2-admin-antd-pro</code></td><td>基于 ant-design-vue-pro 的 Vue 2 后台宿主，通用组件走远程</td></tr></tbody></table><h2 id="在线演示" tabindex="-1">在线演示 <a class="header-anchor" href="#在线演示" aria-label="Permalink to &quot;在线演示&quot;">​</a></h2><p>链接按各包 <code>package.json</code> 的 <code>unpkg</code> 入口生成，打开 npm 已发布的默认版本；页面内容随包发布更新。</p><table tabindex="0"><thead><tr><th>模板 / 示例</th><th>演示地址</th></tr></thead><tbody><tr><td><code>tpl-react-admin-antd-pro</code></td><td><a href="https://unpkg.com/@melt-js/tpl-react-admin-antd-pro/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>tpl-vue2-admin-antd-pro</code></td><td><a href="http://82.156.212.243/@melt-js/tpl-vue2-admin-antd-pro/dist/index.html" target="_blank" rel="noreferrer">演示地址</a>（SFTP 静态托管）</td></tr><tr><td><code>comps-vue2-antd-pro</code></td><td><a href="http://82.156.212.243/@melt-js/comps-vue2-antd-pro/hel_dist/index.html" target="_blank" rel="noreferrer">组件调试页</a>（SFTP 静态托管）</td></tr><tr><td><code>demo-vue2-antd</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue2-antd/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>demo-vue3-antd</code></td><td><a href="https://unpkg.com/@melt-js/demo-vue3-antd/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr><tr><td><code>demo-react-antd</code></td><td><a href="https://unpkg.com/@melt-js/demo-react-antd/dist/index.html" target="_blank" rel="noreferrer">演示地址</a></td></tr></tbody></table><h2 id="提供的方法与工具" tabindex="-1">提供的方法与工具 <a class="header-anchor" href="#提供的方法与工具" aria-label="Permalink to &quot;提供的方法与工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口 / 能力</th><th>用途</th></tr></thead><tbody><tr><td>Vue 2：<code>install</code> / <code>rules</code></td><td>全局注册与校验规则；更多插件能力待补</td></tr><tr><td>React：配套 UI 命名空间</td><td>ProComponents、图标、图表与样式运行时的具体导出待补</td></tr></tbody></table><h2 id="提供的组件" tabindex="-1">提供的组件 <a class="header-anchor" href="#提供的组件" aria-label="Permalink to &quot;提供的组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件 / 分组</th><th>用途</th></tr></thead><tbody><tr><td>Vue 2：<code>DfEmpty</code> / <code>DfPageTitle</code> / <code>DfNavigation</code> / <code>TierRanking</code></td><td>Df 系列与排行组件，完整清单待补</td></tr><tr><td>Vue 3：<code>App</code> / <code>HelloWorld</code></td><td>当前基础示例</td></tr><tr><td>React：<code>Button</code> / <code>Form</code> / <code>Table</code> / <code>ConfigProvider</code></td><td>Ant Design 组件，完整清单和 Pro 命名空间待补</td></tr><tr><td>Vue 2 Pro：<code>ChartCard</code> / <code>Bar</code> / <code>MiniArea</code> / <code>MiniProgress</code> / <code>Radar</code> / <code>RankList</code> / <code>Trend</code> 等图表 12 项</td><td>基于 viser / @antv/data-set 的图表部件</td></tr><tr><td>Vue 2 Pro：<code>AvatarList</code> / <code>Ellipsis</code> / <code>FooterToolbar</code> / <code>IconSelector</code> / <code>NoticeIcon</code> / <code>NumberInfo</code> / <code>StandardFormRow</code> / <code>TagSelect</code> / <code>ArticleListContent</code> / <code>Tree</code> / <code>GlobalSearch</code> / <code>LimitTextArea</code></td><td>页面级部件，可脱离宿主 store 使用</td></tr><tr><td>Vue 2 Pro：<code>dialogPlugin</code> / <code>pageLoadingPlugin</code></td><td>对应原 <code>components/Dialog</code>、<code>components/PageLoading</code> 的插件入口</td></tr></tbody></table><h2 id="接入骨架" tabindex="-1">接入骨架 <a class="header-anchor" href="#接入骨架" aria-label="Permalink to &quot;接入骨架&quot;">​</a></h2><p>最小示例为 <code>demo-vue2-antd</code>、<code>demo-vue3-antd</code> 和 <code>demo-react-antd</code>。不能由系列名称推断三个框架具有同一套组件。</p><p>Vue 2 Pro 一组的宿主骨架是 <code>tpl-vue2-admin-antd-pro</code>：<code>main.js</code> 绑定 Vue 运行时并预加载 <code>comps-vue2-antd-pro</code>，路由就绪后才挂载；<code>src/components/index.js</code> 把远程具名导出统一转出，页面继续用 <code>@/components</code> 的老写法。</p><h2 id="模板简介" tabindex="-1">模板简介 <a class="header-anchor" href="#模板简介" aria-label="Permalink to &quot;模板简介&quot;">​</a></h2><p><code>tpl-react-admin-antd-pro</code> 保留 ant-design-pro 的完整页面、路由、资源与 mock；精确上游快照由模板的 <code>upstream.json</code> 记录。</p><p><code>tpl-vue2-admin-antd-pro</code> 来自 <code>vueComponent/ant-design-vue-pro</code> v3.0.4（MIT），保留 <code>views</code>、<code>router</code>、<code>store</code>、<code>api</code>、<code>mock</code>、<code>utils</code> 等宿主部分，把图表、列表页部件和弹窗 / 加载插件交给 <code>comps-vue2-antd-pro</code> 远程加载；依赖 <code>$store</code> / <code>$route</code> / <code>$t</code> 的 <code>GlobalHeader</code>、<code>MultiTab</code>、<code>Table</code>、<code>SelectLang</code>、<code>SettingDrawer</code> 仍留在模板内。上游原始栈为 vue-cli 5，接入时统一改为仓库 Vue 2 线的 vue-cli 4 与锁定版本。</p><h2 id="从原开源模板快速接入" tabindex="-1">从原开源模板快速接入 <a class="header-anchor" href="#从原开源模板快速接入" aria-label="Permalink to &quot;从原开源模板快速接入&quot;">​</a></h2><p>Vue 2 Pro 一组按下列顺序改造，宿主与提供方分别构建：</p><ol><li>安装 <code>@melt-js/libs-core</code>、<code>@melt-js/comps-vue2-antd-pro</code> 与 <code>@melt-js/tpl-vue2-admin-antd-pro</code>，<code>vue</code> / <code>vue-template-compiler</code> 固定 2.7.16，<code>ant-design-vue</code> 固定 1.7.8。</li><li>提供方先构建，产出 <code>hel_proxy</code> 与 <code>hel_dist</code>；宿主 <code>vue.config.js</code> 把 <code>@melt-js/comps-vue2-antd-pro$</code> 精确别名到对端 <code>hel_proxy/entry.js</code>，避免跨包 TypeScript 源码进入宿主编译。</li><li>宿主 <code>main.js</code> 走 <code>bindVueRuntime</code> + 预加载，<code>loadApp.js</code> 承接原有装配逻辑，启动 loading 与路由就绪一起收尾。</li><li>宿主 <code>src/components/index.js</code> 转出远程具名导出，页面无需改引用；强耦合组件继续留在 <code>src/components</code> 本地。</li></ol><p>以下先列改造顺序，具体文件、配置和代码差异在实现定稿后补齐。</p><ol><li>安装 <code>libs-core</code> 与 <code>comps-react-antd</code>，将宿主 React 运行时与提供方统一。</li><li>在 Umi 的异步 pre-entry 中绑定 React、预加载并校验远程导出，再动态进入应用。</li><li>按模板 <code>config/hel.ts</code> external UI 模块，统一从远程提供方获取 Pro、图标、图表和样式运行时。</li><li>生成远程类型配置，保留上游页面与 mock，构建后执行 <code>check:remote</code> 核对 UI 来源。</li></ol><h2 id="vue-2-pro-逐文件改造" tabindex="-1">Vue 2 Pro 逐文件改造 <a class="header-anchor" href="#vue-2-pro-逐文件改造" aria-label="Permalink to &quot;Vue 2 Pro 逐文件改造&quot;">​</a></h2><p>上游 <code>vueComponent/ant-design-vue-pro</code> v3.0.4 → 本仓库两个包，改造点集中在入口、组件出口、构建配置和依赖四处。</p><table tabindex="0"><thead><tr><th>上游文件</th><th>修改内容</th><th>落点</th><th>验证方式</th></tr></thead><tbody><tr><td><code>src/main.js</code></td><td>原挂载逻辑整体迁到 <code>loadApp.js</code>；<code>main.js</code> 只做 <code>bindVueRuntime({ Vue })</code> 与预加载</td><td><code>tpl-vue2-admin-antd-pro/src/{main.js,loadApp.js}</code></td><td>启动网络请求出现对端 <code>hel-meta.json</code></td></tr><tr><td><code>src/components/{Charts,AvaTarList,...}</code> 共 14 个目录</td><td>整目录删除，改由远程包提供</td><td><code>@melt-js/comps-vue2-antd-pro</code></td><td>包内 grep 不到 <code>@/components/Charts</code> 等残留</td></tr><tr><td><code>src/components/index.js</code></td><td>远程具名导出统一转出，本地组件由默认导出转具名</td><td><code>src/components/index.js</code></td><td>页面里 <code>import { ChartCard } from &#39;@/components&#39;</code> 零改动即可用</td></tr><tr><td><code>src/core/lazy_use.js</code>、<code>src/core/use.js</code></td><td><code>Dialog</code> / <code>PageLoading</code> 换成 <code>dialogPlugin</code> / <code>pageLoadingPlugin</code>，移除 <code>viser-vue</code></td><td>远程包 + 本地核心</td><td>弹窗、全局 loading 正常</td></tr><tr><td><code>vue.config.js</code></td><td>改写为 vue-cli 4：<code>publicPath</code> 生产 <code>./</code>、dev <code>50391</code>、less 走 <code>lessOptions</code>、<code>moment/locale</code> 用 <code>IgnorePlugin</code>、svg 双 <code>oneOf</code>、terser 去 <code>/*!</code> 注释；<code>@melt-js/comps-vue2-antd-pro$</code> 别名到对端 <code>hel_proxy/entry.js</code></td><td>模板根</td><td>构建不再报 TS 源码解析失败</td></tr><tr><td><code>config/plugin.config.js</code></td><td>删除（<code>VUE_APP_PREVIEW</code> 主题预览依赖 <code>webpack-theme-color-replacer</code>）；<code>config/themePluginConfig.js</code> 保留</td><td>模板根</td><td>构建通过，<code>window.umi_plugin_ant_themeVar</code> 仍可用</td></tr><tr><td><code>.env</code></td><td><code>DEV_PORT=50391</code>、<code>PREVIEW_PORT=50392</code>、四个候选入口与 <code>VUE_APP_COMPS_VUE2_ANTD_PRO_HOST</code></td><td>模板 <code>.env</code></td><td>dev 拉 <code>localhost:20013</code></td></tr><tr><td><code>package.json</code></td><td>依赖按仓库 Vue 2 线锁定，补 <code>config.remoteEntries</code> 与 <code>dev</code> / <code>build</code> / <code>publish:stage</code></td><td>模板根</td><td><code>pnpm peers check</code> 无致命项</td></tr></tbody></table><h3 id="依赖口径" tabindex="-1">依赖口径 <a class="header-anchor" href="#依赖口径" aria-label="Permalink to &quot;依赖口径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>依赖</th><th>上游声明</th><th>本仓库锁定</th></tr></thead><tbody><tr><td><code>vue</code> / <code>vue-template-compiler</code></td><td>2.6.14</td><td>2.7.16（成对，<code>packageExtensions</code> 已固定）</td></tr><tr><td><code>ant-design-vue</code></td><td><code>^1.7.8</code></td><td>1.7.8（<code>overrides</code> 把 1.x 全段收敛）</td></tr><tr><td><code>@vue/cli-service</code></td><td><code>~5.0.8</code></td><td>4.5.19（webpack 4）</td></tr><tr><td><code>vue-router</code> / <code>vuex</code> / <code>vue-i18n</code></td><td><code>^3.5.3</code> / <code>^3.6.2</code> / <code>^8.27.1</code></td><td>3.6.5 / 3.6.2 / 8.28.2</td></tr><tr><td><code>axios</code> / <code>moment</code> / <code>core-js</code></td><td><code>^0.26.1</code> / <code>^2.29.2</code> / 3.x</td><td>1.21.0 / 2.31.0 / 3.51.0</td></tr><tr><td><code>less</code> / <code>less-loader</code></td><td>3.x / 5.x</td><td>3.13.1 / 6.2.0</td></tr></tbody></table><p>丢弃的上游 devDependencies：husky、lint-staged、commitlint、stylelint、jest、<code>git-revision-webpack-plugin</code>，以及 <code>&quot;prepare&quot;: &quot;husky install&quot;</code>。</p><h3 id="环境变量与端口" tabindex="-1">环境变量与端口 <a class="header-anchor" href="#环境变量与端口" aria-label="Permalink to &quot;环境变量与端口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>VUE_APP_COMPS_VUE2_ANTD_PRO_HOST</code></td><td>运行入口，由 <code>REMOTE_TARGET</code> 选槽</td></tr><tr><td><code>COMPS_VUE2_ANTD_PRO_LOCAL_ENTRY</code></td><td>本地联调，<code>http://localhost:20013</code></td></tr><tr><td><code>COMPS_VUE2_ANTD_PRO_{SFTP,GITHUB,UNPKG}_ENTRY</code></td><td>三个托管目标的 <code>hel-meta.json</code> 完整路径</td></tr></tbody></table><p>端口：提供方 <code>20013</code>，模板 dev <code>50391</code>、preview <code>50392</code>，均登记在根 <code>ports.json</code>。</p><h3 id="构建与验收顺序" tabindex="-1">构建与验收顺序 <a class="header-anchor" href="#构建与验收顺序" aria-label="Permalink to &quot;构建与验收顺序&quot;">​</a></h3><ol><li><code>pnpm --filter @melt-js/comps-vue2-antd-pro run build</code>（产出 <code>hel_proxy</code> 与 <code>hel_dist</code>）。</li><li><code>pnpm --filter @melt-js/tpl-vue2-admin-antd-pro run build</code>（依赖上一步的 <code>hel_proxy/entry.js</code>，顺序不能倒）。</li><li>验收：模板产物里不应出现 echarts / viser；<code>node scripts/check-package-boundaries.mjs</code> 通过；<code>pnpm run ports:check</code> 除既有项外无新增失败。</li></ol><h3 id="已知风险" tabindex="-1">已知风险 <a class="header-anchor" href="#已知风险" aria-label="Permalink to &quot;已知风险&quot;">​</a></h3><ul><li><code>@ant-design-vue/pro-layout@1.0.13</code> 把 <code>ant-design-vue</code> 与 <code>lodash</code> 写成 <code>dependencies</code>；antd 已用 <code>overrides</code> 收敛到 1.7.8，<code>lodash</code> 仍会作为整包进入模板 bundle。</li><li><code>src/mock</code> 仍在启动链路上，生产产物含 mockjs，与上游行为一致；如需瘦身要按环境条件引入。</li><li>构建期 lint 关闭（<code>lintOnSave: false</code>），<code>pnpm lint</code> 可能报上游风格类问题。</li><li>运行时 <code>libReady</code> 只发布入口的<strong>默认导出对象</strong>，具名导出不会自动带过去。<code>pageLoadingPlugin</code> / <code>dialogPlugin</code> 必须并入默认对象，否则宿主 <code>Vue.use(dialogPlugin)</code> 拿到 <code>undefined</code>，直接抛 <code>TypeError: Cannot read properties of undefined (reading &#39;install&#39;)</code>，整个应用起不来。宿主侧已对两个插件加存在性判断，缺插件只降级不崩。</li><li>模板生产 <code>publicPath</code> 为 <code>./</code>，路由使用 hash 模式；根目录或子目录静态托管都无需额外配置 router base，直达与刷新不会跳到站点根。<code>GIT_HASH</code> 由 <code>DefinePlugin</code> 兜底（上游靠 git-revision-webpack-plugin 注入）。</li></ul><h2 id="待补内容" tabindex="-1">待补内容 <a class="header-anchor" href="#待补内容" aria-label="Permalink to &quot;待补内容&quot;">​</a></h2><ul><li>[ ] 补 Vue 两端与 React 的完整组件 / 方法清单和样式归属。</li><li>[ ] 补 Umi 插件、导入映射和类型配置的逐文件步骤。</li><li>[ ] 补 mock 切换、静态部署及上游版本兼容说明。</li><li>[x] <code>tpl-vue2-admin-antd-pro</code> 静态发布与演示地址（逐文件 diff 见上文）。</li></ul>',38)])])}const m=d(a,[["render",r]]);export{h as __pageData,m as default};
